#define PI acos(-1.0)
#define TAU PI * 2.0

// Vibrant color palette function
vec3 palette(float t) {
    return 0.5 + 0.5 * cos(TAU * (t + vec3(0.000,0.635,0.678)));
}

// Signed Distance Function for an equilateral triangle
float sdEquilateralTriangle(in vec2 p) {
    const float k = sqrt(3.0);
    p.x = abs(p.x) - 1.0;
    p.y = p.y + 1.0 / k;
    if (p.x + k * p.y > 0.0) p = vec2(p.x - k * p.y, -k * p.x - p.y) / 2.0;
    p.x -= clamp(p.x, -2.0, 0.0);
    return -length(p) * sign(p.y);
}

// Sierpinski Triangle SDF
float SDF_SierpinskiTriangle(vec2 p, uint n) {
    vec3 q = vec3(
        (-sqrt(3.0) * p.y - 3.0 * p.x + 1.0) / 3.0,
        (-sqrt(3.0) * p.y + 3.0 * p.x + 1.0) / 3.0,
        (2.0 * sqrt(3.0) * p.y + 1.0) / 3.0
    );

    if (any(lessThan(q, vec3(0.0)))) return sdEquilateralTriangle(p * 2.0) / 2.0;

    float N = exp2(float(n));
    q = 1.0 - q;
    ivec3 i = ivec3(q * N);
    int f = i.x & i.y & i.z;

    if (f == 0) {
        q = 1.0 - q;
        q = mod(q, 1.0 / N);
        return -min(min(q.x, q.y), q.z);
    }

    float s = exp2(floor(log2(float(f)))) * 2.0 / N;
    q = mod(q * 2.0, s) / 2.0 * sqrt(3.0) / 2.0;

    return min(min(q.x, q.y), q.z);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    uv /= 1.0 - uv.y * 1.55;

    vec2 uv0 = uv; // Save original UV for reference
    vec3 col = vec3(0.0);
    float dtot = 0.0;

    // Audio-reactive element
    float audio = texture(iChannel0, vec2(0.001, uv.y * 0.5 + 0.5)).r;

    float n = 1.0 + 7.0 * abs(sin(iTime + audio));
    float h = 0.0015;

    for (float i = 0.0; i < 7.0; i += 1.1) {
        uv.xy *= mat2(cos(iTime), sin(iTime), -sin(iTime), cos(iTime));
        float a = radians(360.0 / 7.0) * i;
        vec2 p = uv;

        // Calculate distance and apply glow
        float d = SDF_SierpinskiTriangle(p, uint(n));
        d = h / abs(d);
        dtot += d;
        h /= 1.1;

        // Add color
        float t = length(uv0) + i * 0.2 + iTime * 0.2;
        col += palette(t) * d * (0.5 + 0.5 * audio); // Modulated by audio
    }

    col += dtot;
    col = pow(col, vec3(0.8)); // Enhance glow
    fragColor = vec4(col * vec3(1.000,0.102,0.878), 0.0);
}
